-- Backend Engineering ("The Fracture") post-game world -- "On-Call Rotation" content.
-- Arc XII -- Field Ops. World row already exists (spine migration
-- 20260810420000_backend_postgame_spine.sql). This migration only adds
-- campaigns -> operations -> missions -> dialogue -> objectives -> challenges -> hints.
--
-- Unlike a normal Act, this world has no single throughline story: each of the
-- eleven lesson missions is a standalone production incident ("the pager just
-- went off"), gated sequentially only for mechanical unlock purposes. The boss
-- mission breaks that pattern deliberately -- three incidents hit at once and
-- the player has to triage, not just diagnose.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-oncall-rotation', 'world-be-oncall-rotation', 'oncall-rotation', 'Field Ops A - On-Call Rotation', 'The campaign is over. The pager isn''t. Eleven standalone incidents and one night where three of them land at once -- everything this pathway taught, replayed cold, without a mission brief to make it easy.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-oncall-rotation-1', 'campaign-be-oncall-rotation', 'the-pager', 'The Pager', 'Six incidents, six pages, no throughline -- connection pools, caches, queues, and the infrastructure underneath all of it, each one starting from nothing but an alert.', 1),
  ('operation-be-oncall-rotation-2', 'campaign-be-oncall-rotation', 'every-alert-answered', 'Every Alert, Answered', 'Deploys, disks, certificates, clocks, and a partition that won''t agree on its own status -- closing with the one night three incidents refuse to wait their turn.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-oncall-rotation-01', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'connection-pool-exhausted', 'Connection Pool Exhausted', 'Every request is timing out waiting for a database connection that never frees up. Somewhere between a leak and a pool sized for a load that stopped being real months ago is the actual answer.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"connection-pool-exhausted-sim"}'::jsonb, '{"xp":448,"credits":86}'::jsonb, false, 1),
  ('mission-be-oncall-rotation-02', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'redis-unavailable', 'Redis Unavailable', 'The cache layer just vanished, and every request that used to cost nothing now hits the database directly. The question isn''t just why Redis went down -- it''s whether the app was ever built to survive it.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"redis-unavailable-sim"}'::jsonb, '{"xp":450,"credits":86}'::jsonb, false, 2),
  ('mission-be-oncall-rotation-03', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'cache-stampede', 'Cache Stampede', 'One hot cache key expires and a thousand simultaneous requests all reach for the database at the exact same instant, to regenerate the exact same answer.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"cache-stampede-sim"}'::jsonb, '{"xp":452,"credits":87}'::jsonb, false, 3),
  ('mission-be-oncall-rotation-04', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'queue-consumer-stopped', 'Queue Consumer Stopped', 'A worker process died silently hours ago. The queue has been growing, unwatched, ever since -- and the first symptom to reach anyone wasn''t an alert. It was a complaint.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"queue-consumer-stopped-sim"}'::jsonb, '{"xp":454,"credits":87}'::jsonb, false, 4),
  ('mission-be-oncall-rotation-05', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'kafka-consumer-lag', 'Kafka Consumer Lag', 'One partition''s consumer has fallen four hours behind while every other partition is caught up. Slow consumer, partition imbalance, or something downstream -- the lag alone won''t say which.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-consumer-lag-sim"}'::jsonb, '{"xp":456,"credits":88}'::jsonb, false, 5),
  ('mission-be-oncall-rotation-06', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-1', 'n-plus-one-query', 'N+1 Query', 'A page that should cost one query is quietly issuing hundreds, and staging never had enough real data for anyone to notice.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"n-plus-one-query-sim"}'::jsonb, '{"xp":458,"credits":88}'::jsonb, false, 6);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-oncall-rotation-07', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'bad-deployment', 'Bad Deployment', 'A routine deploy is throwing errors for a slice of users. Roll forward or roll back -- and guessing wrong costs more than the bug did.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"bad-deployment-sim"}'::jsonb, '{"xp":460,"credits":89}'::jsonb, false, 7),
  ('mission-be-oncall-rotation-08', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'disk-full', 'Disk Full', 'The database host is out of disk and writes are starting to fail. Logs, WAL, table bloat -- guessing wrong wastes the only time there is to fix it.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"disk-full-sim"}'::jsonb, '{"xp":462,"credits":89}'::jsonb, false, 8),
  ('mission-be-oncall-rotation-09', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'tls-certificate-expiry', 'TLS Certificate Expiry', 'Every client suddenly can''t connect, and the error on screen says nothing about why. It looks like a network outage. It isn''t.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"tls-certificate-expiry-sim"}'::jsonb, '{"xp":464,"credits":90}'::jsonb, false, 9),
  ('mission-be-oncall-rotation-10', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'clock-skew', 'Clock Skew', 'A distributed system''s nodes disagree on the time by just enough to break a lease, a token, or the order of a log -- and nothing about the code itself is wrong.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"clock-skew-sim"}'::jsonb, '{"xp":466,"credits":90}'::jsonb, false, 10),
  ('mission-be-oncall-rotation-11', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'partial-network-partition', 'Partial Network Partition', 'Some nodes can reach each other. Some can''t, at the same time. The naive alert can''t decide if the system is up or down, because depending who''s asking, it''s both.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"partial-network-partition-sim"}'::jsonb, '{"xp":468,"credits":90}'::jsonb, false, 11),
  ('mission-be-oncall-rotation-12', 'world-be-oncall-rotation', 'campaign-be-oncall-rotation', 'operation-be-oncall-rotation-2', 'every-alert-answered', 'Every Alert, Answered', 'Three pages, ninety seconds apart. A region wobbling, a rate limiter turning real users away, and a customer report that says they were charged twice. Everything this rotation taught, all at once, with no time to fix them one at a time.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-oncall-rotation-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"every-alert-answered-boss-sim"}'::jsonb, '{"xp":840,"credits":205,"badgeIds":["every-alert-answered"],"skillXp":{"resilience_engineering":25,"observability":15}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-oncall-rotation-01', 1, 'forge', 'Pager. Every request to the dispatch API is timing out -- not failing, just hanging until it eventually gives up. p95 latency is measured in the tens of seconds.'),
  ('mission-be-oncall-rotation-01', 2, 'mira', 'Timeouts waiting on what, though? A slow query and a starved connection pool look identical from the outside until you actually check.'),
  ('mission-be-oncall-rotation-01', 3, 'forge', 'Confirmed: every hung request is stuck waiting to acquire a database connection. The pool has a hard max, and right now every single connection in it is checked out.'),
  ('mission-be-oncall-rotation-01', 4, 'mira', 'Then the real question isn''t whether the pool is too small. It''s why nothing is giving connections back. Start there.'),

  ('mission-be-oncall-rotation-02', 1, 'mira', 'Pager. Redis just dropped off the network entirely -- no warning, no gradual degradation, just gone.'),
  ('mission-be-oncall-rotation-02', 2, 'forge', 'And the database is now carrying triple its normal load, because every request that used to be a cache hit just became a cache miss with nowhere else to go but the DB.'),
  ('mission-be-oncall-rotation-02', 3, 'mira', 'That''s the actual incident. Redis being down for a few minutes should be an inconvenience, not an outage. Something in how the app handles a missing cache turned it into one.'),

  ('mission-be-oncall-rotation-03', 1, 'forge', 'Pager. Database CPU just spiked to 98 percent for about four seconds, completely out of nowhere, then dropped right back down like nothing happened.'),
  ('mission-be-oncall-rotation-03', 2, 'mira', 'Four seconds is short. Short and violent usually means something expired all at once and a crowd showed up to replace it.'),
  ('mission-be-oncall-rotation-03', 3, 'forge', 'One cache key. One expiry. And every request that missed it apparently decided to regenerate it independently, at the exact same moment.'),

  ('mission-be-oncall-rotation-04', 1, 'mira', 'This one didn''t start with a pager at all. Billing just asked why invoices haven''t gone out in over six hours.'),
  ('mission-be-oncall-rotation-04', 2, 'forge', 'Which means whatever''s wrong has been wrong for six hours, and nothing paged anybody about it. That''s two problems, not one.'),
  ('mission-be-oncall-rotation-04', 3, 'mira', 'Find the first problem. We''ll talk about why nobody heard the second one after.'),

  ('mission-be-oncall-rotation-05', 1, 'forge', 'Pager. Consumer lag alert on order-events, partition 3 specifically -- four hours behind. Every other partition on the same topic is fully caught up.'),
  ('mission-be-oncall-rotation-05', 2, 'mira', 'Same topic, same code, same deploy -- one partition behind by hours and the rest fine. That rules out a lot of easy answers before we even start.'),
  ('mission-be-oncall-rotation-05', 3, 'forge', 'CPU and memory on that consumer instance both look completely normal, for what it''s worth.'),

  ('mission-be-oncall-rotation-06', 1, 'mira', 'Pager. The customer order-history page went from forty milliseconds in staging to four seconds in production, overnight, with no deploy in between.'),
  ('mission-be-oncall-rotation-06', 2, 'forge', 'No deploy means the code didn''t change. What changed is how much real data is sitting behind it.'),
  ('mission-be-oncall-rotation-06', 3, 'mira', 'Read the query pattern, not just the page load time. Something in there scales with order count in a way it shouldn''t.'),

  ('mission-be-oncall-rotation-07', 1, 'forge', 'Pager. v2.14.0 went out on a 10 percent canary twenty minutes ago, and error rates just climbed on exactly that slice of traffic.'),
  ('mission-be-oncall-rotation-07', 2, 'mira', 'Twenty minutes in is early enough to still have options. Rolling back undoes it cleanly. Rolling forward with a fix is faster if we''re actually sure what broke.'),
  ('mission-be-oncall-rotation-07', 3, 'forge', 'Only one of those is safe to guess wrong on. Let''s make sure we know which.'),

  ('mission-be-oncall-rotation-08', 1, 'mira', 'Pager. The primary database host is out of disk space, and writes are starting to fail outright.'),
  ('mission-be-oncall-rotation-08', 2, 'forge', 'Out of disk doesn''t tell us what''s eating it. Logs grow slowly and predictably. Table bloat grows with usage. WAL grows when something downstream stops draining it.'),
  ('mission-be-oncall-rotation-08', 3, 'mira', 'Guess wrong here and we clear the wrong thing while the real cause keeps filling the disk back up behind us.'),

  ('mission-be-oncall-rotation-09', 1, 'forge', 'Pager. Every client, all at once, suddenly can''t connect. The error on screen is generic -- something about a connection reset.'),
  ('mission-be-oncall-rotation-09', 2, 'mira', 'Generic and sudden, at midnight, across every client simultaneously -- that pattern rules out most network explanations by itself.'),
  ('mission-be-oncall-rotation-09', 3, 'forge', 'Nothing changed in routing, nothing changed in DNS, the load balancer''s reporting healthy. Whatever broke, it broke on a clock, not a wire.'),

  ('mission-be-oncall-rotation-10', 1, 'mira', 'Pager. A distributed lock is somehow being acquired by two nodes at the same time, even though the leader-election logic hasn''t changed in months.'),
  ('mission-be-oncall-rotation-10', 2, 'forge', 'The code assumes every node agrees on what time it is. That assumption is usually safe enough to stop thinking about entirely.'),
  ('mission-be-oncall-rotation-10', 3, 'mira', 'Usually. Check whether it still holds before you go anywhere near the locking logic itself.'),

  ('mission-be-oncall-rotation-11', 1, 'forge', 'Pager -- or maybe several pagers, saying different things. Some health checks are green. Some are red. They keep flipping.'),
  ('mission-be-oncall-rotation-11', 2, 'mira', 'That''s not flapping. That''s two different nodes describing two different, both technically true, versions of what the cluster looks like right now.'),
  ('mission-be-oncall-rotation-11', 3, 'forge', 'So whether the system is up isn''t a yes-or-no question this time. It depends entirely on which node you ask.'),

  ('mission-be-oncall-rotation-12', 1, 'forge', 'Three pages. Ninety seconds apart. I''m not going to pretend that''s a coincidence you get to enjoy.'),
  ('mission-be-oncall-rotation-12', 2, 'mira', 'us-east-1 is degraded, the rate limiter just started blocking real users, and support is fielding duplicate-charge reports -- all live, all right now.'),
  ('mission-be-oncall-rotation-12', 3, 'forge', 'I can hand you the diagnosis on all three. What I can''t hand you is the order. That part''s yours.'),
  ('mission-be-oncall-rotation-12', 4, 'mira', 'Which one gets your attention first, and why, matters as much as any of the fixes underneath it. Don''t skip that decision just to get to the technical part faster.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-oncall-rotation-01-o1', 'mission-be-oncall-rotation-01', 1, 'Diagnose the exhausted pool', 'Find the evidence that explains why the connection pool never has anything free, even though traffic looks normal.'),
  ('mission-be-oncall-rotation-02-o1', 'mission-be-oncall-rotation-02', 1, 'Diagnose the cache failure mode', 'Choose what actually turned a Redis outage into a database outage.'),
  ('mission-be-oncall-rotation-03-o1', 'mission-be-oncall-rotation-03', 1, 'Identify the stampede', 'Select the log lines that together show this is a stampede, not just one slow query.'),
  ('mission-be-oncall-rotation-04-o1', 'mission-be-oncall-rotation-04', 1, 'Diagnose the silent worker death', 'Find the evidence that explains why invoices stopped going out, not just when it started.'),
  ('mission-be-oncall-rotation-05-o1', 'mission-be-oncall-rotation-05', 1, 'Diagnose the lagging partition', 'Choose the most likely cause of one partition falling hours behind while the rest stay caught up.'),
  ('mission-be-oncall-rotation-06-o1', 'mission-be-oncall-rotation-06', 1, 'Find the N+1', 'Identify the line issuing one query per order instead of one query total.'),
  ('mission-be-oncall-rotation-07-o1', 'mission-be-oncall-rotation-07', 1, 'Decide roll forward or roll back', 'Find the evidence that settles whether rolling back is actually safe here.'),
  ('mission-be-oncall-rotation-08-o1', 'mission-be-oncall-rotation-08', 1, 'Find what''s eating the disk', 'Select the log line that identifies the actual source of the disk pressure.'),
  ('mission-be-oncall-rotation-09-o1', 'mission-be-oncall-rotation-09', 1, 'Diagnose the generic failure', 'Choose the first thing to check when every client fails the same way at once.'),
  ('mission-be-oncall-rotation-10-o1', 'mission-be-oncall-rotation-10', 1, 'Connect the drift to the bug', 'Choose why a disabled NTP sync explains the double-acquired lock.'),
  ('mission-be-oncall-rotation-11-o1', 'mission-be-oncall-rotation-11', 1, 'Diagnose the partial partition', 'Find the evidence that shows this is a partial partition, not a full outage or simple flapping.'),
  ('mission-be-oncall-rotation-12-o1', 'mission-be-oncall-rotation-12', 1, 'Region Outage', 'Decide how to respond to a degraded primary region without making it worse.'),
  ('mission-be-oncall-rotation-12-o2', 'mission-be-oncall-rotation-12', 2, 'Rate-Limiter Misconfiguration', 'Tell a self-inflicted rate-limit rollout apart from a real attack.'),
  ('mission-be-oncall-rotation-12-o3', 'mission-be-oncall-rotation-12', 3, 'Duplicate-Payment Report', 'Find the first thing to check before assuming the payment gateway double-charged anyone.'),
  ('mission-be-oncall-rotation-12-o4', 'mission-be-oncall-rotation-12', 4, 'Triage the Rotation', 'Decide which of the three incidents gets attention first, and defend the order.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-oncall-rotation-01-o1-c1', 'mission-be-oncall-rotation-01-o1', 1, 'investigation', 'Which evidence explains why the pool is empty even though traffic looks normal?', '{"evidence":[{"id":"ev1","label":"Pool configuration","detail":"max pool size is 20 connections, which comfortably covers this service''s normal peak concurrency."},{"id":"ev2","label":"Traffic level","detail":"Request volume over the incident window is flat and unremarkable -- no spike, no deploy, nothing unusual."},{"id":"ev3","label":"Code path","detail":"The report-generation endpoint acquires a client from the pool, but an error thrown mid-query skips the client.release() call in its cleanup path -- so any request that errors leaks its connection permanently."}],"question":"Which evidence explains why the pool is empty even though traffic looks normal?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be-oncall-rotation-02-o1-c1', 'mission-be-oncall-rotation-02-o1', 1, 'multiple_choice', 'Redis becomes unreachable mid-traffic. Every request that used to be a cache hit now goes straight to the database, and error rates spike hard. What actually turned a cache outage into an application outage?', '{"question":"Redis becomes unreachable mid-traffic. Every request that used to be a cache hit now goes straight to the database, and error rates spike hard. What actually turned a cache outage into an application outage?","options":[{"id":"a","text":"Redis itself is unreliable, so this is expected and there is nothing to fix"},{"id":"b","text":"The cache client has no error handling around it -- a failed cache read throws instead of falling back, so a dependency that should be optional is taking the whole page down with it"},{"id":"c","text":"The database should have been sized to handle full load without a cache in the first place"},{"id":"d","text":"This is purely a Redis infrastructure problem and has nothing to do with the application code"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-oncall-rotation-03-o1-c1', 'mission-be-oncall-rotation-03-o1', 1, 'log_analysis', 'Which log lines together show this is a cache stampede, not just a slow query?', '{"logLines":[{"id":"l1","source":"Cache","text":"GET homepage:featured returns a cache MISS at 14:03:00.001 -- its TTL expired at 14:03:00.000, one millisecond earlier."},{"id":"l2","source":"Database","text":"1,842 identical SELECT ... FROM featured_products queries execute between 14:03:00.001 and 14:03:00.250."},{"id":"l3","source":"Metrics","text":"Database CPU spikes to 98 percent for roughly four seconds, then fully recovers."},{"id":"l4","source":"Application","text":"There is no lock or single-flight mechanism around cache regeneration -- every request that misses independently queries the database and rewrites the same cache key."}],"question":"Which log lines together show this is a cache stampede, not just a slow query?"}'::jsonb, '{"requiredLogLineIds":["l2","l4"]}'::jsonb),

  ('mission-be-oncall-rotation-04-o1-c1', 'mission-be-oncall-rotation-04-o1', 1, 'investigation', 'Which evidence explains why invoices actually stopped, not just when the backlog started?', '{"evidence":[{"id":"ev1","label":"Business report","detail":"Billing reports invoices haven''t been emailed in over six hours -- no alert triggered anything internally before that."},{"id":"ev2","label":"Queue depth","detail":"The invoice-email queue has grown steadily and without interruption for the same six-hour window, with no plateau."},{"id":"ev3","label":"Worker process status","detail":"The invoice-email-worker process is not running. Its last log line is an unhandled exception from six hours ago, with no restart or crash-loop attempt since."},{"id":"ev4","label":"Monitoring config","detail":"No alert threshold exists on this queue''s depth or on the worker process''s liveness -- both were assumed to be self-evident from application error rates, which stayed at zero the whole time."}],"question":"Which evidence explains why invoices actually stopped, not just when the backlog started?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be-oncall-rotation-05-o1-c1', 'mission-be-oncall-rotation-05-o1', 1, 'multiple_choice', 'Consumer lag on partition 3 of order-events has grown to four hours while every other partition on the same topic is fully caught up. What''s the most likely cause worth investigating first?', '{"question":"Consumer lag on partition 3 of order-events has grown to four hours while every other partition on the same topic, processed by the same consumer code, is fully caught up. CPU and memory on that consumer instance look completely normal. What''s the most likely cause worth investigating first?","options":[{"id":"a","text":"Add more partitions to the topic to spread the load further"},{"id":"b","text":"The consumer calls a downstream payment-verification API for every message on this partition, and that API''s p99 latency has degraded roughly 40x over the same window -- the consumer isn''t slow, what it''s waiting on is"},{"id":"c","text":"This is a network issue between the broker and the consumer"},{"id":"d","text":"Restart the consumer instance; lag usually clears itself"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-oncall-rotation-06-o1-c1', 'mission-be-oncall-rotation-06-o1', 1, 'code_debugging', 'This endpoint takes 40ms in staging with 3 orders per customer and 4 seconds in production with 200 orders per customer. Which line is actually responsible?', '{"language":"javascript","code":"const orders = await Order.findAll({ where: { customerId } });\nfor (const order of orders) {\n  order.items = await OrderItem.findAll({ where: { orderId: order.id } });\n}","question":"This endpoint takes 40ms in staging with 3 orders per customer and 4 seconds in production with 200 orders per customer. Which line is actually responsible?"}'::jsonb, '{"requiredLineIds":["  order.items = await OrderItem.findAll({ where: { orderId: order.id } });"]}'::jsonb),

  ('mission-be-oncall-rotation-07-o1-c1', 'mission-be-oncall-rotation-07-o1', 1, 'investigation', 'Which evidence tells you rolling back is actually safe, not just fast?', '{"evidence":[{"id":"ev1","label":"Deploy timeline","detail":"v2.14.0 went out on a 10 percent canary twenty minutes ago; v2.13.9 remains on the other 90 percent of traffic."},{"id":"ev2","label":"Error correlation","detail":"100 percent of the new 500 errors are served exclusively by v2.14.0 pods. The v2.13.9 pods serving 90 percent of traffic show a 0 percent error rate over the same window."},{"id":"ev3","label":"Error detail","detail":"The stack trace is a null-pointer exception inside a new, feature-flagged code path that defaults to enabled."}],"question":"Which evidence tells you rolling back is actually safe, not just fast?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-oncall-rotation-08-o1-c1', 'mission-be-oncall-rotation-08-o1', 1, 'log_analysis', 'Which line explains what''s actually consuming the disk?', '{"logLines":[{"id":"d1","source":"Disk","text":"/var/lib/postgresql/14/main is at 100 percent capacity, 0 bytes free."},{"id":"d2","source":"WAL","text":"pg_wal holds 340GB across more than 21,000 segments; the logical replication slot analytics_sync has not advanced in 11 days."},{"id":"d3","source":"Application logs","text":"PostgreSQL log files total 2.1GB, rotated daily -- well within the normal range."},{"id":"d4","source":"Table growth","text":"The orders table''s size and row count both show ordinary, unremarkable growth for this time period."}],"question":"Which line explains what''s actually consuming the disk?"}'::jsonb, '{"requiredLogLineIds":["d2"]}'::jsonb),

  ('mission-be-oncall-rotation-09-o1-c1', 'mission-be-oncall-rotation-09-o1', 1, 'multiple_choice', 'Every client, all at once, starts getting a generic connection-reset or TLS handshake failure. What''s the first thing to check?', '{"question":"Every client, all at once, starts getting a generic connection-reset or TLS handshake failure. DNS resolves fine, the load balancer reports healthy, and nothing changed in network config. What''s the first thing to check?","options":[{"id":"a","text":"Restart the load balancer -- a reset usually clears transient state"},{"id":"b","text":"Whether the TLS certificate served by the load balancer expired -- an expired cert produces exactly this generic, simultaneous, all-clients-at-once failure, and it happens on a clock, not because of a network change"},{"id":"c","text":"Scale up the backend fleet in case it''s a capacity issue"},{"id":"d","text":"Roll back the most recent application deploy"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-oncall-rotation-10-o1-c1', 'mission-be-oncall-rotation-10-o1', 1, 'multiple_choice', 'A distributed lock keeps getting acquired by two nodes at once. NTP sync was disabled on one node three weeks ago and never re-enabled. What''s the connection?', '{"question":"A distributed lock keeps getting acquired by two nodes at once, even though the leader-election code hasn''t changed in months. NTP sync was disabled on one node three weeks ago during a debugging session and never re-enabled. What''s the connection?","options":[{"id":"a","text":"None -- NTP only affects log timestamps, not application logic"},{"id":"b","text":"That node''s clock has drifted enough that its view of the lock''s expiry timestamp no longer matches what the other nodes see -- lease-based locks and leader election both assume every participant agrees on the current time, and clock skew breaks that assumption silently"},{"id":"c","text":"Restarting the affected node will automatically resync its clock and fix the lock"},{"id":"d","text":"This is a network partition, not a clock issue"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-oncall-rotation-11-o1-c1', 'mission-be-oncall-rotation-11-o1', 1, 'investigation', 'Which evidence shows this is a genuine partial partition, not a flapping health check or a full outage?', '{"evidence":[{"id":"ev1","label":"Connectivity matrix","detail":"Node A can reach both Node B and Node C. Node B and Node C cannot reach each other, though both can still reach Node A."},{"id":"ev2","label":"Health dashboard","detail":"Health checks are inconsistently green and red, flipping every few seconds, because each check''s result depends on which node happens to perform it."},{"id":"ev3","label":"On-call runbook","detail":"The paging rule is simply page if a health check fails, with no concept of a health check that is only partially true."}],"question":"Which evidence shows this is a genuine partial partition, not a flapping health check or a full outage?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-oncall-rotation-12-o1-c1', 'mission-be-oncall-rotation-12-o1', 1, 'multiple_choice', 'us-east-1 is reporting elevated error rates across EC2 and RDS. What''s the right move?', '{"question":"us-east-1 is reporting elevated error rates across EC2 and RDS. Your service runs primarily there, with a standby in us-west-2 that has never taken real production traffic. What''s the right move?","options":[{"id":"a","text":"Wait it out -- region issues usually resolve on their own within minutes"},{"id":"b","text":"Immediately fail over 100 percent of traffic to us-west-2 without checking anything first"},{"id":"c","text":"Verify the standby''s data is actually in sync and that it has the capacity to absorb full load before failing over -- sending everyone to an unverified, undersized, or stale standby can be worse than the outage it''s meant to fix"},{"id":"d","text":"Shut the service down entirely until the region recovers"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-oncall-rotation-12-o2-c1', 'mission-be-oncall-rotation-12-o2', 1, 'multiple_choice', 'Legitimate users start getting 429s in volume. What single check would tell you this is a misconfigured rate limiter, not an attack?', '{"question":"Legitimate users start getting 429s in volume. The instinctive read is a DDoS. What single check would tell you this is actually a misconfigured rate limiter, not an attack?","options":[{"id":"a","text":"Total request volume is above baseline -- that alone confirms an attack"},{"id":"b","text":"The blocked requests come from many previously-seen, authenticated accounts with completely normal request patterns, and the 429s began the exact minute a new rate-limit config deployed -- an actual attack doesn''t usually announce itself with a deploy timestamp"},{"id":"c","text":"Block all inbound traffic until the situation is understood"},{"id":"d","text":"Ignore it -- 429 responses are the rate limiter working as intended"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-oncall-rotation-12-o3-c1', 'mission-be-oncall-rotation-12-o3', 1, 'multiple_choice', 'Multiple customers report being charged twice for the same order. What''s the first thing to check?', '{"question":"Multiple customers report being charged twice for the same order. What''s the first thing to check before assuming the payment gateway itself double-charged them?","options":[{"id":"a","text":"Immediately issue refunds to every customer who complains"},{"id":"b","text":"Whether the checkout endpoint is idempotent -- specifically, whether a client retry from a timeout or a double-click against a non-idempotent charge endpoint could create two genuine charges for one order, which is far more common than a gateway charging twice on its own"},{"id":"c","text":"Publicly blame the payment gateway and open a vendor support ticket"},{"id":"d","text":"Disable checkout entirely until the root cause is found"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-oncall-rotation-12-o4-c1', 'mission-be-oncall-rotation-12-o4', 1, 'boss_encounter', 'Having assessed all three incidents, state the triage order and why.', '{"stages":[{"objectiveRef":"mission-be-oncall-rotation-12-o1","label":"Region Outage"},{"objectiveRef":"mission-be-oncall-rotation-12-o2","label":"Rate-Limiter Misconfiguration"},{"objectiveRef":"mission-be-oncall-rotation-12-o3","label":"Duplicate-Payment Report"}],"task":"Having assessed all three, state the triage order and why: handle the rate-limiter misconfiguration first -- reverting a bad config is fast, low-risk, and immediately stops real users from being locked out. Stabilize the region outage second, carefully -- verifying the standby before failing over takes real minutes, and a rushed failover to an unverified target can turn a partial outage into a total one. Contain, then reconcile, the duplicate-payment reports third -- close the idempotency gap so no new duplicate charges occur, then treat the existing ones as a refund and reconciliation process rather than a real-time emergency, since the financial damage stops growing once the retry path is closed."}'::jsonb, '{"requiredObjectiveIds":["mission-be-oncall-rotation-12-o1","mission-be-oncall-rotation-12-o2","mission-be-oncall-rotation-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-oncall-rotation-01-o1-c1', 'orientation', 'Two of these entries rule out too much traffic and too small a pool as the cause. The third explains where the connections actually went.', 15, 1),
  ('mission-be-oncall-rotation-01-o1-c1', 'solution', 'ev3: the missing client.release() on the error path means every failed query leaks a connection permanently -- given enough time, that alone empties a pool of any size.', 30, 2),

  ('mission-be-oncall-rotation-02-o1-c1', 'orientation', 'A cache is supposed to be an optimization, not a dependency the whole page can''t survive without.', 15, 1),
  ('mission-be-oncall-rotation-02-o1-c1', 'solution', 'b: wrap cache reads so a failure falls back to the database (with safeguards like short timeouts and a circuit breaker) instead of throwing -- fail open, not closed, for something that''s meant to be optional.', 30, 2),

  ('mission-be-oncall-rotation-03-o1-c1', 'orientation', 'A slow query would look bad on its own, not synchronized to the same millisecond eighteen hundred times.', 15, 1),
  ('mission-be-oncall-rotation-03-o1-c1', 'solution', 'l2 and l4 together: nearly two thousand requests hit the database with the identical query in the same 250ms window, because nothing in the app stops more than one request from regenerating the same expired key at once.', 30, 2),

  ('mission-be-oncall-rotation-04-o1-c1', 'orientation', 'The queue depth graph tells you when the problem started. It doesn''t tell you why the worker stopped pulling from it.', 15, 1),
  ('mission-be-oncall-rotation-04-o1-c1', 'solution', 'ev3: the worker crashed on an unhandled exception and nothing restarted it -- the queue kept accepting new invoices with nobody left to process them.', 30, 2),

  ('mission-be-oncall-rotation-05-o1-c1', 'orientation', 'Normal CPU and memory on the consumer rule out the consumer itself being the bottleneck -- look at what it''s waiting on, not what it''s doing.', 15, 1),
  ('mission-be-oncall-rotation-05-o1-c1', 'solution', 'b: a per-message call to a downstream dependency that has quietly gotten 40x slower will stall exactly one consumer''s throughput without touching its CPU or memory at all.', 30, 2),

  ('mission-be-oncall-rotation-06-o1-c1', 'orientation', 'Staging never had enough orders per customer for this line to look expensive. Count how many times it actually runs.', 15, 1),
  ('mission-be-oncall-rotation-06-o1-c1', 'solution', 'The OrderItem.findAll inside the loop issues one query per order -- 200 orders means 200 queries where a single query with an IN clause (or an eager-loaded join) would do.', 30, 2),

  ('mission-be-oncall-rotation-07-o1-c1', 'orientation', 'Safety here isn''t about how quickly you can revert -- it''s about whether reverting actually removes the cause.', 15, 1),
  ('mission-be-oncall-rotation-07-o1-c1', 'solution', 'ev2: the error is 100 percent confined to the new version and 0 percent present on the old one, so rolling back the canary removes the cause completely rather than just hiding a symptom.', 30, 2),

  ('mission-be-oncall-rotation-08-o1-c1', 'orientation', 'Two of these entries confirm normal, boring growth. One explains why WAL segments that should have been recycled are still sitting on disk.', 15, 1),
  ('mission-be-oncall-rotation-08-o1-c1', 'solution', 'd2: a stalled replication slot prevents Postgres from ever reclaiming old WAL segments, so they pile up indefinitely regardless of normal log rotation or table growth.', 30, 2),

  ('mission-be-oncall-rotation-09-o1-c1', 'orientation', 'The failure hit every client at the exact same moment, with nothing in routing or DNS changed. That points at something scheduled, not something broken.', 15, 1),
  ('mission-be-oncall-rotation-09-o1-c1', 'solution', 'b: an expired certificate fails every client simultaneously with a generic handshake error, regardless of load balancer or network health -- check the cert''s expiry date before anything else.', 30, 2),

  ('mission-be-oncall-rotation-10-o1-c1', 'orientation', 'The code hasn''t changed. What has changed is whether every node is still measuring time the same way.', 15, 1),
  ('mission-be-oncall-rotation-10-o1-c1', 'solution', 'b: lease and lock expiry are compared against wall-clock time on each node -- a drifted clock can see a lease as already expired while every other node still sees it as valid, and two nodes acquire the same lock.', 30, 2),

  ('mission-be-oncall-rotation-11-o1-c1', 'orientation', 'A full outage would mean nobody can reach anybody. A flapping check would look the same to every observer. Neither matches what''s actually happening here.', 15, 1),
  ('mission-be-oncall-rotation-11-o1-c1', 'solution', 'ev1: A can reach both B and C, but B and C can''t reach each other -- that asymmetry is only possible with a partial partition, where connectivity depends on which pair of nodes you''re asking about.', 30, 2),

  ('mission-be-oncall-rotation-12-o1-c1', 'orientation', 'An unverified standby is a bet, not a guarantee -- weigh what you actually know about it before routing everyone there.', 20, 1),
  ('mission-be-oncall-rotation-12-o1-c1', 'solution', 'c: confirm data sync and capacity on the standby before failing over -- otherwise you''re trading one incident for a worse one.', 35, 2),
  ('mission-be-oncall-rotation-12-o2-c1', 'orientation', 'An attack doesn''t usually start at the exact minute your own team pushed a config change.', 20, 1),
  ('mission-be-oncall-rotation-12-o2-c1', 'solution', 'b: legitimate, previously-seen accounts getting blocked in lockstep with a deploy timestamp points at your own rate limiter, not an attacker.', 35, 2),
  ('mission-be-oncall-rotation-12-o3-c1', 'orientation', 'Payment gateways double-charging on their own is rare. Retries against a non-idempotent endpoint are not.', 20, 1),
  ('mission-be-oncall-rotation-12-o3-c1', 'solution', 'b: check idempotency on the charge endpoint first -- a retried request without an idempotency key is the most common source of a real double charge.', 35, 2),
  ('mission-be-oncall-rotation-12-o4-c1', 'orientation', 'Weigh cost to fix, risk of making it worse, and whether the damage is still growing -- not just which alarm feels loudest.', 20, 1),
  ('mission-be-oncall-rotation-12-o4-c1', 'solution', 'Rate limiter first: fast, safe, and stops active harm to real users. Region outage second: needs a careful, verified failover, not a rushed one. Duplicate payments third: contain via idempotency, then reconcile after, since the damage stops compounding once the retry path is closed.', 35, 2);
